mapper.update:
UPDATE NOTIFICATION
SET IS_READ = 'Y',
    READ_AT = SYSDATE
WHERE NOTIFICATION_NO = #{notificationNo}
  AND RECEIVER_MEMBER_NO = #{memberNo}
  AND IS_READ = 'N'

mapper.select:
SELECT COUNT(*)
FROM NOTIFICATION N
JOIN BUSINESS B
  ON B.MEMBER_NO = N.RECEIVER_MEMBER_NO
WHERE B.BUSINESS_NO = #{businessNo}
  AND N.NOTIFICATION_TYPE = #{notificationType}
  AND N.REFERENCE_TYPE = 'PRODUCT'
  AND N.REFERENCE_NO = #{productNo}
  AND N.IS_READ = 'N'
